import{_ as e,o,c as r,a2 as s}from"./chunks/framework.ORnkkB96.js";const p=JSON.parse('{"title":"Manual das telas","description":"","frontmatter":{},"headers":[],"relativePath":"pt/telas.md","filePath":"pt/telas.md","lastUpdated":1792519643000}'),t={name:"pt/telas.md"};function i(n,a,d,c,m,l){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="manual-das-telas" tabindex="-1">Manual das telas <a class="header-anchor" href="#manual-das-telas" aria-label="Permalink to &quot;Manual das telas&quot;">​</a></h1><p>Uma visão do que cada área da plataforma faz e em que ordem usá-las na primeira vez. O fluxo típico vai de cadastrar câmeras → criar regras → receber notificações, com treino e integração entrando depois.</p><h2 id="cameras" tabindex="-1">Câmeras <a class="header-anchor" href="#cameras" aria-label="Permalink to &quot;Câmeras&quot;">​</a></h2><p>Onde se cadastram as fontes de vídeo. Cada câmera guarda a URL RTSP e a credencial (a senha é <strong>cifrada</strong> no cadastro e só o worker de captura a decifra). Daqui dá para testar a conexão antes de salvar e ver a câmera no vídeo ao vivo.</p><h2 id="grupos" tabindex="-1">Grupos <a class="header-anchor" href="#grupos" aria-label="Permalink to &quot;Grupos&quot;">​</a></h2><p>Organizam as câmeras em conjuntos (por local, por setor), o que simplifica aplicar uma regra ou uma permissão a várias câmeras de uma vez.</p><h2 id="video-ao-vivo" tabindex="-1">Vídeo ao vivo <a class="header-anchor" href="#video-ao-vivo" aria-label="Permalink to &quot;Vídeo ao vivo&quot;">​</a></h2><p>Mostra o stream das câmeras no navegador, servido pelo gateway de mídia pelo mesmo endereço da plataforma — <strong>nenhuma senha de câmera chega à página</strong>. É por aqui que se confere o enquadramento e as zonas de detecção.</p><h2 id="regras" tabindex="-1">Regras <a class="header-anchor" href="#regras" aria-label="Permalink to &quot;Regras&quot;">​</a></h2><p>O coração da operação. Uma regra observa as detecções de uma ou mais câmeras e, quando a condição acontece (um objeto numa zona, permanência acima de um tempo, contagem), dispara uma <strong>ação</strong>: notificar, gravar um snapshot do quadro, chamar um webhook assinado ou um sistema externo. Cooldown e confirmação evitam alarme repetido.</p><h2 id="notificacoes" tabindex="-1">Notificações <a class="header-anchor" href="#notificacoes" aria-label="Permalink to &quot;Notificações&quot;">​</a></h2><p>A central onde as pessoas recebem o que as regras dispararam. O destino de uma notificação são <strong>usuários e grupos</strong> da própria plataforma; a saída externa (WhatsApp, Telegram) sai por integração — tipicamente um webhook para uma ferramenta como o n8n, que entrega na ponta. Cada alerta pode trazer o snapshot do momento e um link de <strong>qualificação</strong> (confirmar se foi um evento real), que alimenta o aprendizado.</p><h2 id="deteccoes-e-historico" tabindex="-1">Detecções e histórico <a class="header-anchor" href="#deteccoes-e-historico" aria-label="Permalink to &quot;Detecções e histórico&quot;">​</a></h2><p>O registro do que foi detectado ao longo do tempo, com filtros por câmera, período e tipo. É o que dá o histórico ao dashboard e o evento ao link de qualificação. A retenção de snapshot e clipe é configurável (padrão: 30 dias).</p><h2 id="treinos" tabindex="-1">Treinos <a class="header-anchor" href="#treinos" aria-label="Permalink to &quot;Treinos&quot;">​</a></h2><p>Onde se treina um modelo próprio a partir das detecções qualificadas. Um job de treino entra na fila e o worker o processa (em GPU, quando disponível). Ao terminar, o aviso chega na central.</p><h2 id="usuarios" tabindex="-1">Usuários <a class="header-anchor" href="#usuarios" aria-label="Permalink to &quot;Usuários&quot;">​</a></h2><p>Cadastro de pessoas e permissões. O login pode ser local ou por identidade externa (<strong>OIDC</strong> ou <strong>LDAP/AD</strong>), que nunca cria conta sozinha — só autentica quem um administrador já vinculou.</p><h2 id="integracoes-mcp" tabindex="-1">Integrações (MCP) <a class="header-anchor" href="#integracoes-mcp" aria-label="Permalink to &quot;Integrações (MCP)&quot;">​</a></h2><p>Expõe o Vision.AI como um <strong>servidor MCP</strong>: um agente do ProAgentHub (ou outro cliente MCP, como Claude Desktop, Cursor ou n8n) consulta a plataforma em linguagem natural. Chega pelo mesmo endereço, em <code>/mcp/</code>.</p>',20)])])}const h=e(t,[["render",i]]);export{p as __pageData,h as default};
